      "number": 10,
      "arFull": "وَلَىِٕنْ اَذَقْنٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَیَقُوْلَنَّ ذَهَبَ السَّیِّاٰتُ عَنِّیْ ؕ اِنَّهٗ لَفَرِحٌ فَخُوْرٌ ۟ۙ",
      "ur": "اور اگر ہم اسے کوئی نعمت چکھائیں اس سختی کے بعد جو اسے پہنچ چکی تھی تو وه کہنے لگتا ہے کہ بس برائیاں مجھ سے جاتی رہیں[1] ، یقیناً وه بڑا ہی اترانے واﻻ شیخی خور ہے.[2]",
      "en": "But if We give him a taste of favor after hardship has touched him, he will surely say, \"Bad times have left me.\" Indeed, he is exultant and boastful -",
      "footnotesUr": "[1] یعنی سمجھتا ہے کہ سختیوں کا دور گزر گیا، اب اسے کوئی تکلیف نہیں آئے گی۔ أُمَّةٌ کے مختلف مفہوم: آیت نمبر ۸ میں أُمَّةٌ کا لفظ آیا ہے۔ یہ قرآن مجید میں مختلف مقامات پر مختلف مفہوم میں استعمال ہوا ہے۔ یہ ام سے مشتق ہے، جس کے معنی قصد کے ہیں۔ یہاں اس کے معنی اس وقت اور مدت کے ہیں جو نزول عذاب کے لیے مقصود ہے۔ (فتح القدیر) سورہ یوسف کی آیت 45«وَادَّكَرَ بَعْدَ أُمَّةٍ» میں یہی مفہوم ہے اس کے علاوہ جن معنوں میں اس کا استعمال ہوا ہے، ان میں ایک امام وپیشوا ہے۔ جیسے «إِنَّ إِبْرَاهِيمَ كَانَ أُمَّةً» ( النحل:120) ملت اور دین ہے، جیسے «إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ» ( الزخرف:23) جماعت اور طائفہ ہے۔ جیسے «وَلَمَّا وَرَدَ مَاءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِنَ النَّاسِ» ( القصص:23)، «وَمِنْ قَوْمِ مُوسَى أُمَّةٌ» (الأعراف:159) وغیرھا۔ وہ مخصوص گروہ یا قوم ہے جس کی طرف کوئی رسول مبعوث ہو۔«وَلِكُلِّ أُمَّةٍ رَسُولٌ» (يونس:47) اس کو امت دعوت بھی کہتے ہیں اور اسی طرح پیغمبر پر ایمان لانے والوں کو بھی امت یا امت اتباع یا امت اجابت کہا جاتا ہے۔ (ابن کثیر)\n[2] یعنی جو کچھ اس کے پاس ہے، اس پر اتراتا اور دوسروں پر فخر و غرور کا اظہار کرتا ہے۔ تاہم ان صفات مذمومہ سے اہل ایمان اور صاحب اعمال صالحہ مستشنٰی ہیں جیسا کہ اگلی آیت سے واضح ہے۔",
