      "arFull": "اِلَّا الَّذِیْنَ صَبَرُوْا وَعَمِلُوا الصّٰلِحٰتِ ؕ اُولٰٓىِٕكَ لَهُمْ مَّغْفِرَةٌ وَّاَجْرٌ كَبِیْرٌ ۟",
