      "arFull": "فَلَعَلَّكَ تَارِكٌ بَعْضَ مَا یُوْحٰۤی اِلَیْكَ وَضَآىِٕقٌ بِهٖ صَدْرُكَ اَنْ یَّقُوْلُوْا لَوْلَاۤ اُنْزِلَ عَلَیْهِ كَنْزٌ اَوْ جَآءَ مَعَهٗ مَلَكٌ ؕ اِنَّمَاۤ اَنْتَ نَذِیْرٌ ؕ وَاللّٰهُ عَلٰی كُلِّ شَیْءٍ وَّكِیْلٌ ۟ؕ",
      "ur": "پس شاید کہ آپ اس وحی کے کسی حصے کو چھوڑ دینے والے ہیں جو آپ کی طرف نازل کی جاتی ہے اور اس سے آپ کا دل تنگ ہے، صرف ان کی اس بات پر کہ اس پر کوئی خزانہ کیوں نہیں اترا؟ یا اس کے ساتھ کوئی فرشتہ ہی آتا، سن لیجئے! آپ تو صرف ڈرانے والے ہی ہیں[1] اور ہر چیز کا ذمہ دار اللہ تعالیٰ ہے.",
      "en": "Then would you possibly leave [out] some of what is revealed to you,[550] or is your breast constrained by it because they say, \"Why has there not been sent down to him a treasure or come with him an angel?\" But you are only a warner. And Allāh is Disposer of all things.",
      "footnotesUr": "[1] مشرکین نبی (صلى الله عليه وسلم) کی بابت کہتے رہتے تھے کہ اس کے ساتھ کوئی فرشتہ نازل کیوں نہیں ہوتا، یا اس کی طرف سے کوئی خزانہ کیوں نہیں اتار دیا جاتا، (الفرقان-18)ایک دوسرے مقام پر فرمایا گیا ”ہمیں معلوم ہے کہ یہ لوگ آپ کی بابت جو باتیں کہتے ہیں“ ان سے آپ کا سینہ تنگ ہوتا ہے۔ (سورۃ الحجر:98) اس آیت میں انہی باتوں کے حوالے سے کہا جا رہا ہے کہ شاید آپ کا سینہ تنگ ہو اور کچھ باتیں جو آپ کی طرف وحی کی جاتی ہیں اور وہ مشرکین پر گراں گزرتی ہیں ممکن ہے آپ وہ انہیں سنانا پسند نہ کریں آپ کا کام صرف انذار و تبلیغ ہے، وہ آپ ہر صورت میں کئے جائیں۔",
