      "arFull": "فَعَقَرُوْهَا فَقَالَ تَمَتَّعُوْا فِیْ دَارِكُمْ ثَلٰثَةَ اَیَّامٍ ؕ ذٰلِكَ وَعْدٌ غَیْرُ مَكْذُوْبٍ ۟",
