      "number": 77,
      "arFull": "وَلَمَّا جَآءَتْ رُسُلُنَا لُوْطًا سِیْٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَّقَالَ هٰذَا یَوْمٌ عَصِیْبٌ ۟",
      "ur": "جب ہمارے بھیجے ہوئے فرشتے لوط کے پاس پہنچے تو وه ان کی وجہ سے بہت غمگین ہوگئے [1] اور دل ہی دل میں کڑھنے لگے اور کہنے لگے کہ آج کا دن بڑی مصیبت کا دن ہے.",
      "en": "And when Our messengers, [the angels], came to Lot, he was anguished for them and felt for them great discomfort[568] and said, \"This is a trying day.\"",
      "footnotesUr": "[1] حضرت لوط (عليه السلام) کی اس سخت پریشانی کی وجہ مفسرین نے لکھی ہے کہ یہ فرشتے نوجوانوں کی شکل میں آئے تھے، جو بےریش تھے، جس سے حضرت لوط (عليه السلام) نے اپنی قوم کی عادت قبیحہ کے پیش نظر سخت خطرہ محسوس کیا۔ کیونکہ ان کو یہ پتہ نہیں تھا کہ آنے والے یہ نوجوان، مہمان نہیں ہیں، بلکہ اللہ کے بھیجے ہوئے فرشتے ہیں جو اس قوم کو ہلاک کرنے کے لئے آئے ہیں۔",
      "footnotesEn": "[568] Prophet Lot feared for the safety and honor of his guests.",
