      "arFull": "وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ النَّاسَ اُمَّةً وَّاحِدَةً وَّلَا یَزَالُوْنَ مُخْتَلِفِیْنَ ۟ۙ",
      "ur": "اگر آپ کا پروردگار چاہتا تو سب لوگوں کو ایک ہی راه پر ایک گروه کر دیتا۔ وه تو برابر اختلاف کرنے والے ہی رہیں گے.",
