      "number": 119,
      "arFull": "اِلَّا مَنْ رَّحِمَ رَبُّكَ ؕ وَلِذٰلِكَ خَلَقَهُمْ ؕ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَاَمْلَـَٔنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ اَجْمَعِیْنَ ۟",
      "ur": "بجز ان کے جن پر آپ کا رب رحم فرمائے، انہیں تو اسی لئے پیدا کیا ہے[1] ، اور آپ کے رب کی یہ بات پوری ہے کہ میں جہنم کو جنوں اور انسانوں سب سے پر کروں گا.[2]",
      "en": "Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, \"I will surely fill Hell with jinn and men all together.\"",
      "footnotesUr": "[1] ”اسی لئے“ کا مطلب بعض نے اختلاف اور بعض نے رحمت لیا ہے۔ دونوں صورتوں میں مفہوم یہ ہوگا کہ ہم نے انسانوں کو آزمائش کے لئے پیدا کیا ہے۔ جو دین حق سے اختلاف کا راستہ اختیار کرے گا، وہ آزمائش میں ناکام اور جو اسے اپنا لے گا، وہ کامیاب اور رحمت الٰہی کا مستحق ہوگا۔\n[2] یعنی اللہ کی تقدیر اور قضاء میں یہ بات ثبت ہے کہ کچھ لوگ ایسے ہونگے جو جنت کے اور کچھ ایسے ہونگے جو جہنم کے مستحق ہوں گے اور جنت و جہنم کو انسانوں اور جنوں سے بھر دیا جائے گا۔ جیسا کہ حدیث میں ہے، نبی نے فرمایا: جنت اور دوزخ آپس میں جھگڑ پڑیں، جنت نے کہا، کیا بات ہے کہ میرے اندر وہی لوگ آئیں گے جو کمزور اور معاشرے کے گرے پڑے لوگ ہوں گے؟ جہنم نے کہا میرے اندر تو بڑے بڑے جبار اور متکبر قسم کے لوگ ہوں گے\" اللہ تعالٰی نے، جنت سے فرمایا تو میری رحمت کی مظہر ہے، تیرے ذریعے سے میں جس پر چاہوں اپنا رحم کروں۔ اور جہنم سے اللہ تعالٰی نے فرمایا تو میرے عذاب کی مظہر ہے تیرے ذریعے سے میں جس کو چاہوں سزا دوں۔ اللہ تعالٰی جنت اور دوزخ دونوں کو بھر دے گا۔ جنت میں ہمیشہ اس کا فضل ہوگا، حتٰی کہ اللہ تعالٰی ایسی مخلوق پیدا فرمائے گا جو جنت کے باقی ماندہ رقبے میں رہے گی اور جہنم، جہنمیوں کی کثرت کے باوجود «هَلْ مِنْ مَزِيدٍ» نعرہ بلند کرے گی، یہاں تک کہ اللہ تعالٰی اس میں اپنا قدم رکھے گا جس پر جہنم پکار اٹھے گی قط قط وعزتک، بس، بس، تیری عزت و جلال کی قسم \"۔ (صحيح بخاري، كتاب التوحيد، باب ما جاء في قوله تعالى إن رحمة الله قريب من المحسنين ، وتفسير سورة ق - مسلم كتاب الجنة باب النار يدخلها الجبارون والجنة يدخلها الضعفاء)",
      "footnotesEn": null,
